}

static inline uint32_t deposit32(uint32_t value, int start, int length, /* <=== deposit32 */ 
                                 uint32_t fieldval)
{
    uint32_t mask;
    assert(start >= 0 && length > 0 && length <= 32 - start);
    mask = (~0U >> (32 - length)) << start;
    return (value & ~mask) | ((fieldval << start) & mask);
}

static ssize_t qemu_send_packet_async_with_flags(NetClientState *sender, /* <=== qemu_send_packet_async_with_flags */ 
                                                 unsigned flags,
                                                 const uint8_t *buf, int size,
                                                 NetPacketSent *sent_cb)
{
    NetQueue *queue;
    int ret;

#ifdef DEBUG_NET
    printf("qemu_send_packet_async:\n");
    qemu_hexdump(stdout, "net", buf, size);
#endif

    if (sender->link_down || !sender->peer) {
        return size;
    }

    /* Let filters handle the packet first */
    ret = filter_receive(sender, NET_FILTER_DIRECTION_TX,
                         sender, flags, buf, size, sent_cb);
    if (ret) {
        return ret;
    }

    ret = filter_receive(sender->peer, NET_FILTER_DIRECTION_RX,
                         sender, flags, buf, size, sent_cb);
    if (ret) {
        return ret;
    }

    queue = sender->peer->incoming_queue;

    return qemu_net_queue_send(queue, sender, flags, buf, size, sent_cb);
}

ssize_t qemu_send_packet_async(NetClientState *sender, /* <=== qemu_send_packet_async */ 
                               const uint8_t *buf, int size,
                               NetPacketSent *sent_cb)
{
    return qemu_send_packet_async_with_flags(sender, QEMU_NET_PACKET_FLAG_NONE,
                                             buf, size, sent_cb);
}

static inline bool memory_region_is_ram(MemoryRegion *mr) /* <=== memory_region_is_ram */ 
{
    return mr->ram;
}

ssize_t qemu_send_packet(NetClientState *nc, const uint8_t *buf, int size) /* <=== qemu_send_packet */ 
{
    return qemu_send_packet_async(nc, buf, size, NULL);
}

static void emac_store_desc(MSF2EmacState *s, EmacDesc *d, hwaddr desc) /* <=== emac_store_desc */ 
{
    /* Convert from host endianness into LE. */
    d->pktaddr = cpu_to_le32(d->pktaddr);
    d->pktsize = cpu_to_le32(d->pktsize);
    d->next = cpu_to_le32(d->next);

    address_space_write(&s->dma_as, desc, MEMTXATTRS_UNSPECIFIED, d, sizeof *d);
}

MemTxResult address_space_write(AddressSpace *as, hwaddr addr, /* <=== address_space_write */ 
                                MemTxAttrs attrs,
                                const void *buf, hwaddr len);

static inline __attribute__((__always_inline__)) /* <=== address_space_read */ 
MemTxResult address_space_read(AddressSpace *as, hwaddr addr,
                               MemTxAttrs attrs, void *buf,
                               hwaddr len)
{
    MemTxResult result = MEMTX_OK;
    hwaddr l, addr1;
    void *ptr;
    MemoryRegion *mr;
    FlatView *fv;

    if (__builtin_constant_p(len)) {
        if (len) {
            RCU_READ_LOCK_GUARD();
            fv = address_space_to_flatview(as);
            l = len;
            mr = flatview_translate(fv, addr, &addr1, &l, false, attrs);
            if (len == l && memory_access_is_direct(mr, false)) {
                ptr = qemu_map_ram_ptr(mr->ram_block, addr1);
                memcpy(buf, ptr, len);
            } else {
                result = flatview_read_continue(fv, addr, attrs, buf, len,
                                                addr1, l, mr);
            }
        }
    } else {
        result = address_space_read_full(as, addr, attrs, buf, len);
    }
    return result;
}

static inline uint32_t extract32(uint32_t value, int start, int length) /* <=== extract32 */ 
{
    assert(start >= 0 && length > 0 && length <= 32 - start);
    return (value >> start) & (~0U >> (32 - length));
}

ssize_t qemu_receive_packet(NetClientState *nc, const uint8_t *buf, int size) /* <=== qemu_receive_packet */ 
{
    if (!qemu_can_receive_packet(nc)) {
        return 0;
    }

    return qemu_net_queue_receive(nc->incoming_queue, buf, size);
}

static inline bool memory_access_is_direct(MemoryRegion *mr, bool is_write) /* <=== memory_access_is_direct */ 
{
    if (is_write) {
        return memory_region_is_ram(mr) && !mr->readonly &&
               !mr->rom_device && !memory_region_is_ram_device(mr);
    } else {
        return (memory_region_is_ram(mr) && !memory_region_is_ram_device(mr)) ||
               memory_region_is_romd(mr);
    }
}

static inline FlatView *address_space_to_flatview(AddressSpace *as) /* <=== address_space_to_flatview */ 
{
    return qatomic_rcu_read(&as->current_map);
}

int qemu_can_receive_packet(NetClientState *nc) /* <=== qemu_can_receive_packet */ 
{
    if (nc->receive_disabled) {
        return 0;
    } else if (nc->info->can_receive &&
               !nc->info->can_receive(nc)) {
        return 0;
    }
    return 1;
}

